     1	package br.com.marealta;
     2	
     3	import br.com.marealta.plan.RatePlan;
     4	import br.com.marealta.plan.RatePlans;
     5	import com.fasterxml.jackson.core.JsonProcessingException;
     6	import com.fasterxml.jackson.databind.JsonNode;
     7	import com.fasterxml.jackson.databind.ObjectMapper;
     8	import java.time.LocalDate;
     9	import java.time.format.DateTimeParseException;
    10	
    11	/** Pedido de reserva já validado quanto ao formato. */
    12	public record NewReservation(
    13	        int roomNumber,
    14	        String guestName,
    15	        String guestEmail,
    16	        String guestCpf,
    17	        LocalDate checkIn,
    18	        LocalDate checkOut,
    19	        int guests,
    20	        RatePlan plan,
    21	        String companyCode) {
    22	
    23	    public static NewReservation parse(ObjectMapper mapper, String body) {
    24	        JsonNode json;
    25	        try {
    26	            json = mapper.readTree(body);
    27	        } catch (JsonProcessingException e) {
    28	            throw ApiError.invalidRequest("O corpo não é um JSON válido");
    29	        }
    30	        if (json == null || !json.isObject()) {
    31	            throw ApiError.invalidRequest("O corpo deve ser um objeto JSON");
    32	        }
    33	        LocalDate checkIn = date(json, "checkIn");
    34	        LocalDate checkOut = date(json, "checkOut");
    35	        if (!checkOut.isAfter(checkIn)) {
    36	            throw ApiError.invalidRequest("A saída deve ser depois da entrada");
    37	        }
    38	        int guests = integer(json, "guests");
    39	        if (guests < 1) {
    40	            throw ApiError.invalidRequest("É preciso ao menos um hóspede");
    41	        }
    42	        String planCode = text(json, "ratePlan");
    43	        RatePlan plan = RatePlans.find(planCode)
    44	                .orElseThrow(() -> ApiError.invalidRequest("Plano de tarifa desconhecido: " + planCode));
    45	        JsonNode company = json.get("companyCode");
    46	        return new NewReservation(
    47	                integer(json, "roomNumber"),
    48	                text(json, "guestName"),
    49	                text(json, "guestEmail"),
    50	                text(json, "guestCpf"),
    51	                checkIn,
    52	                checkOut,
    53	                guests,
    54	                plan,
    55	                company != null && company.isTextual() ? company.asText() : null);
    56	    }
    57	
    58	    private static String text(JsonNode json, String field) {
    59	        JsonNode node = json.get(field);
    60	        if (node == null || !node.isTextual() || node.asText().isBlank()) {
    61	            throw ApiError.invalidRequest("Campo obrigatório ausente ou inválido: " + field);
    62	        }
    63	        return node.asText();
    64	    }
    65	
    66	    private static int integer(JsonNode json, String field) {
    67	        JsonNode node = json.get(field);
    68	        if (node == null || !node.isIntegralNumber() || !node.canConvertToInt()) {
    69	            throw ApiError.invalidRequest("Campo obrigatório ausente ou inválido: " + field);
    70	        }
    71	        return node.asInt();
    72	    }
    73	
    74	    private static LocalDate date(JsonNode json, String field) {
    75	        try {
    76	            return LocalDate.parse(text(json, field));
    77	        } catch (DateTimeParseException e) {
    78	            throw ApiError.invalidRequest("Data fora do formato AAAA-MM-DD: " + field);
    79	        }
    80	    }
    81	}
