    29	                SELECT 1 FROM reservations
    30	                WHERE room_number = ? AND status <> 'CANCELLED' AND check_in < ? AND check_out > ?
    31	                LIMIT 1""")) {
    32	            s.setInt(1, roomNumber);
    33	            s.setDate(2, Date.valueOf(checkOut));
    34	            s.setDate(3, Date.valueOf(checkIn));
