    43	                INSERT INTO reservations (room_number, guest_name, guest_email, guest_cpf, check_in, check_out,
    44	                    guests, rate_plan, subtotal, discount, total, status, amount_paid)
    45	                VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 'PENDING', 0)
    46	                RETURNING """ + " " + COLUMNS)) {
    47	            s.setInt(1, n.roomNumber());
    48	            s.setString(2, n.guestName());
    49	            s.setString(3, n.guestEmail());
    50	            s.setString(4, n.guestCpf());
    51	            s.setDate(5, Date.valueOf(n.checkIn()));
    52	            s.setDate(6, Date.valueOf(n.checkOut()));
    53	            s.setInt(7, n.guests());
    54	            s.setString(8, n.plan().code());
    55	            s.setBigDecimal(9, quote.subtotal());
    56	            s.setBigDecimal(10, quote.discount());
    57	            s.setBigDecimal(11, quote.total());
