     9	public final class Database implements AutoCloseable {
    10	
    11	    @FunctionalInterface
    12	    public interface Work<T> {
    13	        T apply(Connection connection) throws SQLException;
    14	    }
    15	
    16	    private final HikariDataSource dataSource;
    17	
    18	    public Database(String url, String user, String password) {
    19	        HikariConfig config = new HikariConfig();
    20	        config.setJdbcUrl(url);
    21	        config.setUsername(user);
    22	        config.setPassword(password);
    23	        config.setInitializationFailTimeout(60_000);
    24	        this.dataSource = new HikariDataSource(config);
    25	        createSchema();
    26	    }
    27	
    28	    private void createSchema() {
    29	        inTransaction(c -> {
    30	            try (Statement s = c.createStatement()) {
    31	                s.execute("SELECT pg_advisory_xact_lock(0)");
    32	                s.execute("""
    33	                        CREATE TABLE IF NOT EXISTS reservations (
    34	                            id BIGSERIAL PRIMARY KEY,
    35	                            room_number INT NOT NULL,
    36	                            guest_name TEXT NOT NULL,
    37	                            guest_email TEXT NOT NULL,
    38	                            guest_cpf TEXT NOT NULL,
    39	                            check_in DATE NOT NULL,
    40	                            check_out DATE NOT NULL,
    41	                            guests INT NOT NULL,
    42	                            rate_plan TEXT NOT NULL,
    43	                            subtotal NUMERIC(12,2) NOT NULL,
    44	                            discount NUMERIC(12,2) NOT NULL,
    45	                            total NUMERIC(12,2) NOT NULL,
    46	                            status TEXT NOT NULL,
    47	                            amount_paid NUMERIC(12,2) NOT NULL,
    48	                            refund NUMERIC(12,2)
    49	                        )""");
    50	                s.execute("""
    51	                        CREATE TABLE IF NOT EXISTS messages (
    52	                            id BIGSERIAL PRIMARY KEY,
    53	                            channel TEXT NOT NULL,
    54	                            recipient TEXT NOT NULL,
    55	                            subject TEXT NOT NULL,
    56	                            body TEXT NOT NULL
    57	                        )""");
    58	            }
    59	            return null;
    60	        });
    61	    }
    62	
    63	    public <T> T read(Work<T> work) {
    64	        try (Connection c = dataSource.getConnection()) {
    65	            return work.apply(c);
    66	        } catch (SQLException e) {
    67	            throw new IllegalStateException(e);
    68	        }
    69	    }
    70	
    71	    public <T> T inTransaction(Work<T> work) {
    72	        try (Connection c = dataSource.getConnection()) {
    73	            c.setAutoCommit(false);
    74	            try {
    75	                T result = work.apply(c);
    76	                c.commit();
    77	                return result;
    78	            } catch (SQLException | RuntimeException e) {
    79	                c.rollback();
    80	                throw e;
    81	            }
    82	        } catch (SQLException e) {
    83	            throw new IllegalStateException(e);
    84	        }
    85	    }
    86	
    87	    @Override
    88	    public void close() {
    89	        dataSource.close();
    90	    }
    91	}
