     9	public final class ReportService {
    10	    private static final Pattern MONTH = Pattern.compile("\\d{4}-\\d{2}");
    11	
    12	    private final Database db;
    13	    private final ReservationRepository reservations = new ReservationRepository();
    14	
    15	    public ReportService(Database db) {
    16	        this.db = db;
    17	    }
    18	
    19	    public String occupancy(String dateParam) {
    20	        LocalDate night = parseDate(dateParam);
    21	        List<Reservation> occupying = db.read(c -> reservations.paidOccupying(c, night));
    22	        StringBuilder csv = new StringBuilder("room,type,reservation,check_in,check_out\n");
    23	        for (Reservation r : occupying) {
    24	            csv.append(r.roomNumber()).append(',').append(r.room().type()).append(',').append(r.id()).append(',')
    25	                    .append(r.checkIn()).append(',').append(r.checkOut()).append('\n');
    26	        }
    27	        long rooms = occupying.stream().map(Reservation::roomNumber).distinct().count();
    28	        return csv.append("total,").append(rooms).append('/').append(Rooms.all().size()).append('\n').toString();
    29	    }
    30	
    31	    public String revenue(String monthParam) {
    32	        YearMonth month = parseMonth(monthParam);
    33	        List<Reservation> kept = db.read(c ->
    34	                reservations.keptMoney(c, month.atDay(1), month.plusMonths(1).atDay(1)));
    35	        StringBuilder csv = new StringBuilder("reservation,room,check_in,check_out,status,amount\n");
    36	        BigDecimal sum = Money.ZERO;
    37	        for (Reservation r : kept) {
    38	            csv.append(r.id()).append(',').append(r.roomNumber()).append(',').append(r.checkIn()).append(',')
    39	                    .append(r.checkOut()).append(',').append(r.status()).append(',').append(r.kept()).append('\n');
    40	            sum = sum.add(r.kept());
    41	        }
    42	        return csv.append("total,").append(sum).append('\n').toString();
    43	    }
