     1	package br.com.marealta;
     2	
     3	import br.com.marealta.plan.RatePlan;
     4	import br.com.marealta.plan.RatePlans;
     5	import com.fasterxml.jackson.annotation.JsonIgnore;
     6	import com.fasterxml.jackson.annotation.JsonProperty;
     7	import java.math.BigDecimal;
     8	import java.time.LocalDate;
     9	import java.time.temporal.ChronoUnit;
    10	
    11	public record Reservation(
    12	        long id,
    13	        int roomNumber,
    14	        String guestName,
    15	        String guestEmail,
    16	        String guestCpf,
    17	        LocalDate checkIn,
    18	        LocalDate checkOut,
    19	        int guests,
    20	        String ratePlan,
    21	        BigDecimal subtotal,
    22	        BigDecimal discount,
    23	        BigDecimal total,
    24	        ReservationStatus status,
    25	        BigDecimal amountPaid,
    26	        BigDecimal refund) {
    27	
    28	    @JsonProperty("nights")
    29	    public int nights() {
    30	        return (int) ChronoUnit.DAYS.between(checkIn, checkOut);
    31	    }
    32	
    33	    @JsonIgnore
    34	    public RatePlan plan() {
    35	        return RatePlans.find(ratePlan).orElseThrow();
    36	    }
    37	
    38	    @JsonIgnore
    39	    public Room room() {
    40	        return Rooms.find(roomNumber).orElseThrow();
    41	    }
    42	
    43	    /** Pago menos devolvido: o que fica com a pousada. */
    44	    @JsonIgnore
    45	    public BigDecimal kept() {
    46	        return refund == null ? amountPaid : amountPaid.subtract(refund);
    47	    }
    48	
    49	    public Reservation confirm() {
    50	        requireStatus("confirmada", ReservationStatus.PENDING);
    51	        return with(ReservationStatus.CONFIRMED, total, refund);
    52	    }
    53	
    54	    public Reservation startStay() {
    55	        requireStatus("com check-in", ReservationStatus.CONFIRMED);
    56	        return with(ReservationStatus.CHECKED_IN, amountPaid, refund);
    57	    }
    58	
    59	    public Reservation endStay() {
    60	        requireStatus("com check-out", ReservationStatus.CHECKED_IN);
    61	        return with(ReservationStatus.CHECKED_OUT, amountPaid, refund);
    62	    }
    63	
    64	    public Reservation cancel() {
    65	        requireStatus("cancelada", ReservationStatus.PENDING, ReservationStatus.CONFIRMED);
    66	        BigDecimal refunded = status == ReservationStatus.PENDING ? Money.ZERO : plan().refund(amountPaid);
    67	        return with(ReservationStatus.CANCELLED, amountPaid, refunded);
    68	    }
    69	
    70	    public void requirePaid() {
    71	        if (!status.isPaid()) {
    72	            throw ApiError.operationNotAllowed("Só existe comprovante de reserva paga");
    73	        }
    74	    }
    75	
    76	    private void requireStatus(String action, ReservationStatus... allowed) {
    77	        for (ReservationStatus s : allowed) {
    78	            if (s == status) {
    79	                return;
    80	            }
    81	        }
    82	        throw ApiError.operationNotAllowed("Reserva " + status + " não pode ser " + action);
    83	    }
    84	
    85	    private Reservation with(ReservationStatus newStatus, BigDecimal newPaid, BigDecimal newRefund) {
