    19	    /** Serializa as reservas concorrentes do mesmo quarto até o fim da transação. */
    20	    public void lockRoom(Connection c, int roomNumber) throws SQLException {
    21	        try (PreparedStatement s = c.prepareStatement("SELECT pg_advisory_xact_lock(?)")) {
