    44	                    guests, rate_plan, subtotal, discount, total, status, amount_paid)
    45	                VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 'PENDING', 0)
    46	                RETURNING """ + " " + COLUMNS)) {
    47	            s.setInt(1, n.roomNumber());
