    52	            s.setDate(6, Date.valueOf(n.checkOut()));
    53	            s.setInt(7, n.guests());
    54	            s.setString(8, n.plan().code());
    55	            s.setBigDecimal(9, quote.subtotal());
    56	            s.setBigDecimal(10, quote.discount());
    57	            s.setBigDecimal(11, quote.total());
