    86	    /** Reservas pagas que ocupam o quarto na noite, por número do quarto. */
    87	    public List<Reservation> paidOccupying(Connection c, LocalDate night) throws SQLException {
    88	        return query(c, "WHERE status IN ('CONFIRMED', 'CHECKED_IN', 'CHECKED_OUT') AND check_in <= ? AND check_out > ? "
    89	                + "ORDER BY room_number, id", night, night);
