    92	    /** Reservas que começam no período e deixaram dinheiro com a pousada. */
    93	    public List<Reservation> keptMoney(Connection c, LocalDate from, LocalDate toExclusive) throws SQLException {
    94	        return query(c, "WHERE check_in >= ? AND check_in < ? AND amount_paid - COALESCE(refund, 0) > 0 "
    95	                + "ORDER BY check_in, id", from, toExclusive);
