    98	    private List<Reservation> query(Connection c, String clause, LocalDate first, LocalDate second) throws SQLException {
    99	        try (PreparedStatement s = c.prepareStatement("SELECT " + COLUMNS + " FROM reservations " + clause)) {
   100	            s.setDate(1, Date.valueOf(first));
   101	            s.setDate(2, Date.valueOf(second));
   102	            List<Reservation> result = new ArrayList<>();
   103	            try (ResultSet rs = s.executeQuery()) {
   104	                while (rs.next()) {
   105	                    result.add(map(rs));
   106	                }
   107	            }
   108	            return result;
   109	        }
   110	    }
