    15	
    16	    public Reservation create(NewReservation request) {
    17	        Room room = Rooms.find(request.roomNumber()).orElseThrow(() -> ApiError.roomNotFound(request.roomNumber()));
    18	        Quote quote = request.plan().quote(new Stay(room, request.checkIn(), request.checkOut(), request.companyCode()));
    19	        if (request.guests() > room.capacity()) {
    20	            throw ApiError.capacityExceeded(room.capacity());
    21	        }
    22	        return db.inTransaction(c -> {
    23	            reservations.lockRoom(c, room.number());
    24	            if (reservations.hasConflict(c, room.number(), request.checkIn(), request.checkOut())) {
    25	                throw ApiError.roomUnavailable();
    26	            }
    27	            return reservations.insert(c, request, quote);
    28	        });
    29	    }
    30	
    31	    public Reservation get(String id) {
    32	        return db.read(c -> reservations.find(c, parseId(id), false)
    33	                .orElseThrow(() -> ApiError.reservationNotFound(id)));
    34	    }
    35	
    36	    public Reservation confirm(String id) {
    37	        return db.inTransaction(c -> {
    38	            Reservation confirmed = lock(c, id).confirm();
    39	            reservations.update(c, confirmed);
    40	            messages.record(c, "EMAIL", confirmed.guestEmail(), ConfirmationEmail.SUBJECT,
    41	                    ConfirmationEmail.body(confirmed));
    42	            return confirmed;
    43	        });
    44	    }
    45	
    46	    public Reservation cancel(String id) {
    47	        return db.inTransaction(c -> {
    48	            Reservation cancelled = lock(c, id).cancel();
    49	            reservations.update(c, cancelled);
    50	            return cancelled;
    51	        });
    52	    }
    53	
    54	    public Reservation checkIn(String id) {
    55	        return db.inTransaction(c -> {
    56	            Reservation r = lock(c, id).startStay();
    57	            reservations.update(c, r);
    58	            return r;
    59	        });
    60	    }
    61	
    62	    public Receipt checkOut(String id) {
    63	        return db.inTransaction(c -> {
    64	            Reservation r = lock(c, id).endStay();
    65	            reservations.update(c, r);
    66	            return Receipt.of(r);
    67	        });
    68	    }
    69	
    70	    public Receipt document(String id) {
    71	        Reservation r = get(id);
    72	        r.requirePaid();
    73	        return Receipt.of(r);
    74	    }
